def parse_bool(text):
    if text not in ('true', 'false'):
        raise ValueError('invalid boolean')
    return text == 'true'

import html

def render(text):
    return '<div>' + html.escape(text) + '</div>'

import copy

def clone(config):
    return copy.deepcopy(config)

def minimum(items):
    result = items[0]
    for value in items:
        result = min(result, value)
    return result
